// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product, IBeacon, Fixed18, PackedFixed18, PackedUFixed18, UFixed18, IOracleProvider, JumpRateUtilizationCurve, PayoffDefinition, PayoffDefinitionLib, IProduct, ICollateral, IController, IIncentivizer, IMultiInvoker} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    FakeController fake;

    function setUp() public {
        c = new Product();
        fake = new FakeController();
        FakeOracle oracleF = new FakeOracle();
        Dummy dummy = new Dummy();
        fake.configure(IOracleProvider(address(oracleF)), address(dummy));
        fake.attach(c);
        fake.setCoordinatorFor(IProduct(address(c)), 1);
    }

    function testFuzz_property(address caller, uint256 newMaintenanceRaw) public {
        // coordinator owner is address(0) (unset); exclude it and the zero address so the
        // caller is NEVER the coordinator owner -> admissible domain is all non-owners
        vm.assume(caller != address(0));
        uint256 newMaintenance = bound(newMaintenanceRaw, 1, 1e30);

        UFixed18 before = c.maintenance();

        vm.prank(caller);
        bool ok;
        try c.updateMaintenance(UFixed18.wrap(newMaintenance)) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: a call from a non-owner of the product's coordinator must revert
        // and must NOT change the stored maintenance parameter.
        assertTrue(!ok && UFixed18.unwrap(c.maintenance()) == UFixed18.unwrap(before), "non-owner must not be able to update maintenance");
    }
}

contract FakeOracle is IOracleProvider {
    uint256 public v;

    function sync() external returns (OracleVersion memory) {
        v += 1;
        return OracleVersion(v, block.timestamp, Fixed18.wrap(0));
    }

    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion(v, block.timestamp, Fixed18.wrap(0));
    }

    function atVersion(uint256 version) external pure returns (OracleVersion memory) {
        return OracleVersion(version, 0, Fixed18.wrap(0));
    }
}

// accepts every call so collateral().settleProduct / incentivizer().sync succeed
contract Dummy {
    fallback() external {}
}

contract FakeController is IController {
    address dummy_;
    IOracleProvider oracle_;
    mapping(uint256 => Coordinator) _coordinators;
    mapping(address => uint256) _coordinatorFor;

    function configure(IOracleProvider o, address d) external {
        oracle_ = o;
        dummy_ = d;
    }

    function setCoordinatorFor(IProduct p, uint256 id) external {
        _coordinatorFor[address(p)] = id;
    }

    // initialize the product with this contract as controller (msg.sender must be a contract)
    function attach(IProduct p) external {
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "T",
            symbol: "T",
            payoffDefinition: PayoffDefinition(PayoffDefinitionLib.PayoffType(0), PayoffDefinitionLib.PayoffDirection(0), bytes30(0)),
            oracle: oracle_,
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(type(uint256).max),
            utilizationCurve: JumpRateUtilizationCurve(
                PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedFixed18.wrap(0), PackedUFixed18.wrap(0)
            )
        });
        p.initialize(info);
    }

    function collateral() external view returns (ICollateral) { return ICollateral(dummy_); }
    function incentivizer() external view returns (IIncentivizer) { return IIncentivizer(dummy_); }
    function productBeacon() external view returns (IBeacon) { return IBeacon(address(0)); }
    function multiInvoker() external view returns (IMultiInvoker) { return IMultiInvoker(address(0)); }
    function coordinators(uint256 id) external view returns (Coordinator memory) { return _coordinators[id]; }
    function coordinatorFor(IProduct p) external view returns (uint256) { return _coordinatorFor[address(p)]; }
    function protocolFee() external view returns (UFixed18) { return UFixed18.wrap(0); }
    function minFundingFee() external view returns (UFixed18) { return UFixed18.wrap(0); }
    function liquidationFee() external view returns (UFixed18) { return UFixed18.wrap(0); }
    function incentivizationFee() external view returns (UFixed18) { return UFixed18.wrap(0); }
    function minCollateral() external view returns (UFixed18) { return UFixed18.wrap(0); }
    function programsPerProduct() external view returns (uint256) { return 0; }
    function pauser() external view returns (address) { return address(0); }
    function paused() external view returns (bool) { return false; }
    function initialize(ICollateral, IIncentivizer, IBeacon) external {}
    function createCoordinator() external pure returns (uint256) { revert(); }
    function updateCoordinatorPendingOwner(uint256, address) external {}
    function acceptCoordinatorOwner(uint256) external {}
    function updateCoordinatorTreasury(uint256, address) external {}
    function createProduct(uint256, IProduct.ProductInfo calldata) external pure returns (IProduct) { revert(); }
    function updateCollateral(ICollateral) external {}
    function updateIncentivizer(IIncentivizer) external {}
    function updateProductBeacon(IBeacon) external {}
    function updateMultiInvoker(IMultiInvoker) external {}
    function updateProtocolFee(UFixed18) external {}
    function updateMinFundingFee(UFixed18) external {}
    function updateLiquidationFee(UFixed18) external {}
    function updateIncentivizationFee(UFixed18) external {}
    function updateMinCollateral(UFixed18) external {}
    function updateProgramsPerProduct(uint256) external {}
    function updatePauser(address) external {}
    function updatePaused(bool) external {}
    function isProduct(IProduct p) external view returns (bool) { return _coordinatorFor[address(p)] != 0; }
    function owner() external view returns (address) { return address(0); }
    function owner(uint256) external view returns (address) { return address(0); }
    function owner(IProduct p) external view returns (address) { return address(0); }
    function treasury() external view returns (address) { return address(0); }
    function treasury(uint256) external view returns (address) { return address(0); }
    function treasury(IProduct) external view returns (address) { return address(0); }
}
